export const MONEY_QUERY_ERROR_CODES = Object.freeze([
  'MONEY_QUERY_INVALID','MONEY_QUERY_TIMEOUT','MONEY_QUERY_BUSY','MONEY_QUERY_TOO_HEAVY',
  'MONEY_QUERY_SCAN_LIMIT','MONEY_QUERY_HISTORY_LIMIT','MONEY_QUERY_WINDOW','MONEY_QUERY_UNAVAILABLE',
]);

// Only this route's short reviewed envelope may cross an MCP error boundary.
// Never infer authority from arbitrary HTTP text or an unknown support code.
export function moneyQueryErrorText(body) {
  if(!MONEY_QUERY_ERROR_CODES.includes(body?.code)||typeof body.error!=='string'||body.error.length<1||body.error.length>700)return null;
  const reason=typeof body.reason==='string'&&/^[a-z_]{1,40}$/.test(body.reason)?` (Reason: ${body.reason})`:'';
  return ownerOutputText(`${body.error} (Support code: ${body.code})${reason}`);
}

