export const MONEY_OVERVIEW_NEXT_STEP = 'Do not repeat brain_money_overview for this answer. Read brain_money_guide and continue with permitted evidence or one bounded raw fin_transactions investigation. Keep the actual accounts and dates of that slice; it is not a certified whole-book total. State unknown coverage and missing dollar impact. If calendar evidence is unavailable, say so and use explicit dates supported by the request or records, without guessing relative dates. Always complete the answer from available evidence.';

export function unavailableMoneyQuery(code) {
  const confidence = unknownMoneyConfidence('The requested money rows could not be read; their dollar impact is unknown.',
    'Read the requested accounts and dates with a complete bounded query or source statements. Use available overview amounts or document figures separately, with their sources and dates.');
  return { status: 'partial', rows: null, row_count: null, truncated: false,
    code: MONEY_QUERY_ERROR_CODES.includes(code) ? code : 'MONEY_QUERY_UNAVAILABLE',
    confidence, confidence_text: confidenceText(confidence), next_step: MONEY_OVERVIEW_NEXT_STEP + ' A failed lifecycle lookup means amount unknown; never report $0 or none for removed, superseded or pending rows until a complete lookup succeeds. For raw fin_transactions reads omit from/through and to, retain period_from/period_to, and put explicit posted_on bounds in SQL. Use pending, removed_at, removal_reason and superseded_by_id; fin_transactions has no status or superseded_by column.' };
}

// Older Workers and failed transports cannot certify an unscored amount.
// Preserve any readable rows/calendar, but make absent confidence explicit.
export function withMoneyConfidence(result) {
  const c = result?.confidence;
  const level = c?.percent >= 90 ? 'High' : c?.percent >= 70 ? 'Medium' : 'Low';
  const strings = values => Array.isArray(values) && values.every(value => typeof value === 'string' && value.length > 0);
  const valid = c && Number.isSafeInteger(c.percent) && c.percent >= 0 && c.percent <= 100 && c.level === level &&
    strings(c.reasons) && strings(c.missing) && (c.percent === 100 ? !c.reasons.length && !c.missing.length : c.reasons.length && c.missing.length);
  const confidence = valid ? c : unknownMoneyConfidence('The tool returned no verified confidence evidence.',
    'Read connections, complete date coverage, successful sync times and supporting uncertain amounts with a scoring-capable tool.');
  return { ...(result && typeof result === 'object' && !Array.isArray(result) ? result : {}),
    ...Object.fromEntries(['answer', 'coverage_text', 'error', 'next_step', 'note']
      .filter(field => typeof result?.[field] === 'string').map(field => [field, ownerOutputText(result[field])])),
    confidence, confidence_text: confidenceText(confidence) };
}

// A transport failure has no trustworthy body or calendar. Both MCP surfaces
// use this fixed policy instead of reflecting private upstream error text.
export function unavailableMoneyOverview() {
  const confidence = unknownMoneyConfidence();
  return { status: 'partial', today: null, time_zone: null, time_zone_basis: 'unavailable', window: null,
    accounts: null, months: null,
    confidence, confidence_text: confidenceText(confidence),
    limitations: [{ scope: 'overview', code: 'MONEY_OVERVIEW_UNAVAILABLE', text: 'Could not read the money overview: calendar, accounts, coverage and monthly totals are unavailable. Their dollar impact is unknown.' }],
    coverage_text: 'Could not read the money overview. Calendar evidence, account coverage and monthly totals are unavailable; missing dollar impact is unknown.\n' + ownerEvidenceNote(confidence),
    next_step: MONEY_OVERVIEW_NEXT_STEP };
}

